    \centering
    \makebox[0pt]{\includegraphics[width=15cm]{figs/UMAP_clusters.pdf}}
    \caption{2D UMAP Visualization of the feature embedding space with data from S10 as an example. Commands and conditions are depicted in colors and symbols, respectively. The zoom-in area shows that the data distributions of the same command from different conditions are mostly overlapped, suggesting that our visual speech representation is robust to environment factors.}
    \label{fig:umap}
